-- Migration 128: Convert opening balance (224) to capital (222)
-- 1) Update any journal lines pointing to 224 (ID: 00000000-0000-0000-0000-000000003002 or 00000000-0000-0000-0000-000000000224)
--    to point to 222 (ID: 00000000-0000-0000-0000-000000002202).
UPDATE journal_lines 
SET account_id = '00000000-0000-0000-0000-000000002202' 
WHERE account_id IN ('00000000-0000-0000-0000-000000003002', '00000000-0000-0000-0000-000000000224');

-- 2) Delete the '224' account
DELETE FROM accounts 
WHERE code = '224' 
   OR id IN ('00000000-0000-0000-0000-000000003002', '00000000-0000-0000-0000-000000000224');
